// MK4 — Browser storage adapter + dev-server log sink. Platform glue only:
// no game rules live here. The logic layer produces serialized saves and log
// entries; this module persists them (localStorage) and, in dev, mirrors log
// entries to the Vite middleware sink so they land in a text file on the dev
// machine — including entries generated by a phone playing over the LAN.

import { DEFAULT_BATTLE_SETTINGS } from './logic/constants';
import {
  MAX_METRIC_LOG_ENTRIES,
  MAX_TURN_LOG_ENTRIES,
  MetricLogEntry,
  SelectionLogEntry,
  TurnLogEntry,
  WizardLogEntry,
} from './logic/logger';
import { BattleSettings } from './logic/types';

const SAVE_KEY = 'breach:save';
const METRICS_LOG_KEY = 'breach:log:metrics';
const TURN_LOG_KEY = 'breach:log:turns';
const WIZARD_LOG_KEY = 'breach:log:wizard'; // Alpha 0.2.0 §5.4 wizard records
const SELECTION_LOG_KEY = 'breach:log:selection'; // Alpha 0.3.0 §21.2
const CONFIG_KEY = 'breach:config';
const MAX_WIZARD_LOG_ENTRIES = 500;
const MAX_SELECTION_LOG_ENTRIES = 500;

function readArray<T>(key: string): T[] {
  try {
    const raw = localStorage.getItem(key);
    const arr = raw ? (JSON.parse(raw) as T[]) : [];
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}

function writeArray<T>(key: string, arr: T[], cap: number): void {
  const trimmed = arr.length > cap ? arr.slice(arr.length - cap) : arr;
  try {
    localStorage.setItem(key, JSON.stringify(trimmed));
  } catch {
    // quota pressure: drop the older half and retry once, else give up quietly
    try {
      localStorage.setItem(key, JSON.stringify(trimmed.slice(Math.floor(trimmed.length / 2))));
    } catch {
      /* logging must never break the game */
    }
  }
}

// ---- MK4.1 save/restore ----

export function saveBattle(json: string, turn: number): void {
  try {
    localStorage.setItem(SAVE_KEY, json);
    console.info(`[breach] state saved (turn ${turn})`);
  } catch (e) {
    console.warn('[breach] autosave failed', e);
  }
}

export function loadBattleJson(): string | null {
  try {
    return localStorage.getItem(SAVE_KEY);
  } catch {
    return null;
  }
}

export function clearBattleSave(): void {
  try {
    localStorage.removeItem(SAVE_KEY);
  } catch {
    /* ignore */
  }
}

// ---- MK5.4 menu-settings persistence (persists across sessions; nothing
// resets it implicitly — "Reset to Defaults" in the UI is the only reset) ----

// Alpha 0.3.0 (cfgV 5): the persisted shape is now BattleSettings — the
// player-CHOSEN values only. Removed: `hackerBonusEnabled` (that passive is now
// the Hacker's Skill records, §6.1) and the persisted `strongColors`/
// `strongShapes` (resolved per battle from the selected Hacker, §5.4).
// Renamed: `noMatchDamage` -> `reinforcedConnection` (§11.1),
// `nmdChargeAwareBot` -> `reinforcedChargeAwareBot`, and `playerHp`/`enemyHp` ->
// `manualHackerLink`/`manualSystemIce` (used only when Normal LINK is OFF).
// Obsolete persisted fields from earlier builds are ignored without crashing:
// the migration copies surviving fields explicitly and carries the old
// no-match-damage / manual-HP values forward so a player's choices survive.
const MENU_CONFIG_VERSION = 5;

export function loadMenuSettings(): BattleSettings {
  try {
    const raw = localStorage.getItem(CONFIG_KEY);
    if (!raw) return { ...DEFAULT_BATTLE_SETTINGS };
    const c = JSON.parse(raw) as Partial<BattleSettings> & {
      cfgV?: number;
      // pre-0.3.0 field names, read for one-way migration only
      noMatchDamage?: unknown;
      nmdChargeAwareBot?: unknown;
      playerHp?: unknown;
      enemyHp?: unknown;
    };
    const bool = (v: unknown, fallback: boolean): boolean => (typeof v === 'boolean' ? v : fallback);
    const int = (v: unknown, min: number, max: number, fallback: number): number =>
      Number.isInteger(v) && (v as number) >= min && (v as number) <= max ? (v as number) : fallback;
    const D = DEFAULT_BATTLE_SETTINGS;
    const cfg: BattleSettings = {
      enemyMatching: bool(c.enemyMatching, D.enemyMatching),
      singleAxisPayout: bool(c.singleAxisPayout, D.singleAxisPayout),
      maxCascadeSteps:
        c.maxCascadeSteps === null || (Number.isInteger(c.maxCascadeSteps) && (c.maxCascadeSteps as number) >= 0 && (c.maxCascadeSteps as number) <= 9)
          ? (c.maxCascadeSteps as number | null)
          : D.maxCascadeSteps,
      // §11.1 — reuse the existing setting path rather than adding a second toggle
      reinforcedConnection: bool(c.reinforcedConnection, bool(c.noMatchDamage, D.reinforcedConnection)),
      normalLink: bool(c.normalLink, D.normalLink),
      manualHackerLink: int(c.manualHackerLink, 1, 9999, int(c.playerHp, 1, 9999, D.manualHackerLink)),
      manualSystemIce: int(c.manualSystemIce, 1, 9999, int(c.enemyHp, 1, 9999, D.manualSystemIce)),
      hintEnabled: bool(c.hintEnabled, D.hintEnabled),
      hintDelaySeconds: int(c.hintDelaySeconds, 1, 60, D.hintDelaySeconds),
      reinforcedChargeAwareBot: bool(c.reinforcedChargeAwareBot, bool(c.nmdChargeAwareBot, D.reinforcedChargeAwareBot)),
    };
    if (c.cfgV !== MENU_CONFIG_VERSION) {
      // Re-stamp so migration never re-runs, and so obsolete fields (dropped by
      // the explicit field copy above) are not re-persisted.
      saveMenuSettings(cfg);
    }
    return cfg;
  } catch {
    return { ...DEFAULT_BATTLE_SETTINGS };
  }
}

export function saveMenuSettings(c: BattleSettings): void {
  try {
    localStorage.setItem(CONFIG_KEY, JSON.stringify({ ...c, cfgV: MENU_CONFIG_VERSION }));
  } catch {
    /* ignore */
  }
}

// ---- MK4.3 log persistence ----

function postToSink(kind: 'metrics' | 'turn' | 'wizard' | 'selection', entry: unknown): void {
  // dev-server sink only exists under `npm run dev`; guarded so non-Vite
  // runtimes (tests) can import this module safely
  if (!(import.meta as { env?: { DEV?: boolean } }).env?.DEV) return;
  void fetch('/__breach/log', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ kind, at: new Date().toISOString(), entry }),
  }).catch(() => {
    /* sink unreachable (e.g. preview build) — localStorage still has the logs */
  });
}

export function appendMetricsLog(entry: MetricLogEntry): void {
  const arr = readArray<MetricLogEntry>(METRICS_LOG_KEY);
  arr.push(entry);
  writeArray(METRICS_LOG_KEY, arr, MAX_METRIC_LOG_ENTRIES);
  postToSink('metrics', entry);
}

export function appendTurnLogs(entries: TurnLogEntry[]): void {
  if (!entries.length) return;
  const arr = readArray<TurnLogEntry>(TURN_LOG_KEY);
  arr.push(...entries);
  writeArray(TURN_LOG_KEY, arr, MAX_TURN_LOG_ENTRIES);
  for (const e of entries) postToSink('turn', e);
}

// Alpha 0.2.0 §5.4/§21.4 — wizard invocations are their own record stream,
// preserved alongside (never overwriting) the natural battle outcome.
export function appendWizardLog(entry: WizardLogEntry): void {
  const arr = readArray<WizardLogEntry>(WIZARD_LOG_KEY);
  arr.push(entry);
  writeArray(WIZARD_LOG_KEY, arr, MAX_WIZARD_LOG_ENTRIES);
  postToSink('wizard', entry);
}

// Alpha 0.3.0 §21.2 — COMMITTED selection events and final Run creation.
export function appendSelectionLog(entry: SelectionLogEntry): void {
  const arr = readArray<SelectionLogEntry>(SELECTION_LOG_KEY);
  arr.push(entry);
  writeArray(SELECTION_LOG_KEY, arr, MAX_SELECTION_LOG_ENTRIES);
  postToSink('selection', entry);
}

export function readLogs(): {
  metrics: MetricLogEntry[];
  turns: TurnLogEntry[];
  wizard: WizardLogEntry[];
  selection: SelectionLogEntry[];
} {
  return {
    metrics: readArray(METRICS_LOG_KEY),
    turns: readArray(TURN_LOG_KEY),
    wizard: readArray(WIZARD_LOG_KEY),
    selection: readArray(SELECTION_LOG_KEY),
  };
}

export function wipeLogs(): void {
  try {
    localStorage.removeItem(METRICS_LOG_KEY);
    localStorage.removeItem(TURN_LOG_KEY);
    localStorage.removeItem(WIZARD_LOG_KEY);
    localStorage.removeItem(SELECTION_LOG_KEY);
  } catch {
    /* ignore */
  }
}
